var ids=['settings','settings-account','settings-devices','settings-general','settings-appearance','settings-voice','settings-notifications','settings-connections','settings-billing','settings-privacy','settings-shortcuts','settings-about','settings--sign-out','settings-billing--plan'];
['Light/Clean','Dark/Clean'].forEach(function(app){var p=H.page('Proto macOS '+app.split('/')[0]);ids.forEach(function(id){var matches=p.layers.filter(function(l){return l.name==='Screen/macos/'+app+'/'+id;});if(matches.length!==1)throw new Error(id+' count '+matches.length);var s=matches[0],borders=[],rows=[],links=[],text=[],overflow=[];function walk(l){if(l.style&&(l.style.borders||[]).some(function(b){return b.enabled;})&&!/^traffic-|^arc$|^track$/.test(l.name))borders.push(l.name);if(l.name.indexOf('form:')===0)rows.push(l.frame.height);if(l.name.indexOf('link:')===0)links.push(l.name);if(l.type==='Text')text.push(l.text);if(l.parent&&l.parent.name==='control'&&l.frame.x+l.frame.width>l.parent.frame.width+1)overflow.push(l.name);(l.layers||[]).forEach(walk);}walk(s);console.log(JSON.stringify({id:id,app:app,frame:s.id,page:p.name,w:s.frame.width,h:s.frame.height,x:s.frame.x,y:s.frame.y,borders:borders,rows:Array.from(new Set(rows)),badLinks:links.filter(function(n){return / \d+$/.test(n);}),overflow:overflow,hasTokens:text.indexOf('41,200 of 500,000 tokens')>=0,hasVersion:text.indexOf('1.4 (build 2026.09.15)')>=0}));});});